1	import { describe, it, expect } from "vitest";
2	import { TERM, POWERTRAIN_PLAIN, PROTOCOL_PLAIN, resolve } from "./labels";
3	
4	describe("TERM dictionary", () => {
5	  it("BEV powertrain has correct plain label", () => {
6	    expect(POWERTRAIN_PLAIN["BEV"]).toBe("Electric only");
7	  });
8	  it("PHEV powertrain has correct plain label", () => {
9	    expect(POWERTRAIN_PLAIN["PHEV"]).toBe("Plug-in hybrid");
10	  });
11	  it("EPA has correct plain label", () => {
12	    expect(PROTOCOL_PLAIN["EPA"]).toBe("Government test");
13	  });
14	  it("range geek label is Range", () => {
15	    expect(TERM.range.geek).toBe("Range");
16	    expect(TERM.range.plain).toBe("Estimated distance");
17	  });
18	  it("msrp geek label is MSRP", () => {
19	    expect(TERM.msrp.geek).toBe("MSRP");
20	    expect(TERM.msrp.plain).toBe("Starting price");
21	  });
22	});
23	
24	describe("resolve()", () => {
25	  it("returns plain when plainMode=true", () => {
26	    expect(resolve(TERM.range, true)).toBe("Estimated distance");
27	  });
28	  it("returns geek when plainMode=false", () => {
29	    expect(resolve(TERM.range, false)).toBe("Range");
30	  });
31	  it("passes through plain strings unchanged", () => {
32	    expect(resolve("Static label", true)).toBe("Static label");
33	    expect(resolve("Static label", false)).toBe("Static label");
34	  });
35	});
