1	import { useEffect, useRef, useState, useCallback } from "react";
2	import "leaflet/dist/leaflet.css";
3	import type { Vehicle } from "../types";
4	import type { ThermalOutputs } from "../lib/thermal";
5	import { VEHICLE_COLORS } from "../lib/compare-colors";
6	
7	// Leaflet is lazy-imported in useEffect to ensure it has access to window.
8	import type * as L from "leaflet";
9	
10	// Fix broken icon paths under Vite asset bundling (known gotcha)
11	function fixLeafletIcons(leaflet: typeof L) {
12	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
13	  delete (leaflet.Icon.Default.prototype as any)._getIconUrl;
14	  leaflet.Icon.Default.mergeOptions({
15	    iconUrl: "/leaflet-markers/marker-icon.png",
16	    iconRetinaUrl: "/leaflet-markers/marker-icon-2x.png",
17	    shadowUrl: "/leaflet-markers/marker-shadow.png",
18	  });
19	}
20	
21	// Default map center: Toronto City Hall
22	const DEFAULT_CENTER: [number, number] = [43.6532, -79.3832];
23	
24	// 15 hardcoded Ontario DCFC stations (fallback when no OCM API key).
25	// Locations are well-known DCFC sites; power levels approximate.
26	interface Station {
27	  id: string;
28	  name: string;
29	  lat: number;
30	  lng: number;
31	  kw: number;
32	  network: string;
33	}
34	
35	const ONTARIO_DCFC_FALLBACK: Station[] = [
36	  { id: "on-01", name: "Electrify Canada — Square One", lat: 43.593, lng: -79.642, kw: 350, network: "Electrify Canada" },
37	  { id: "on-02", name: "Electrify Canada — Erin Mills", lat: 43.551, lng: -79.715, kw: 350, network: "Electrify Canada" },
38	  { id: "on-03", name: "Tesla Supercharger — Toronto (Bay St)", lat: 43.648, lng: -79.381, kw: 250, network: "Tesla" },
39	  { id: "on-04", name: "Tesla Supercharger — Mississauga", lat: 43.612, lng: -79.637, kw: 250, network: "Tesla" },
40	  { id: "on-05", name: "Petro-Canada DCFC — Burlington", lat: 43.316, lng: -79.797, kw: 100, network: "Petro-Canada" },
41	  { id: "on-06", name: "Tesla Supercharger — Hamilton", lat: 43.257, lng: -79.870, kw: 250, network: "Tesla" },
42	  { id: "on-07", name: "Electrify Canada — Kitchener", lat: 43.449, lng: -80.492, kw: 350, network: "Electrify Canada" },
43	  { id: "on-08", name: "Tesla Supercharger — London", lat: 42.984, lng: -81.249, kw: 250, network: "Tesla" },
44	  { id: "on-09", name: "Electrify Canada — Guelph", lat: 43.545, lng: -80.247, kw: 350, network: "Electrify Canada" },
45	  { id: "on-10", name: "Petro-Canada DCFC — Brampton", lat: 43.685, lng: -79.762, kw: 100, network: "Petro-Canada" },
46	  { id: "on-11", name: "Tesla Supercharger — Oshawa", lat: 43.897, lng: -78.865, kw: 250, network: "Tesla" },
47	  { id: "on-12", name: "Electrify Canada — Kingston", lat: 44.233, lng: -76.481, kw: 350, network: "Electrify Canada" },
48	  { id: "on-13", name: "Tesla Supercharger — Barrie", lat: 44.389, lng: -79.690, kw: 250, network: "Tesla" },
49	  { id: "on-14", name: "Electrify Canada — Ottawa (Trainyards)", lat: 45.410, lng: -75.668, kw: 350, network: "Electrify Canada" },
50	  { id: "on-15", name: "Petro-Canada DCFC — Sudbury", lat: 46.494, lng: -81.001, kw: 100, network: "Petro-Canada" },
51	];
52	
53	interface MapPanelProps {
54	  vehicles: Vehicle[];
55	  thermals: Record<string, ThermalOutputs>;
56	  center?: [number, number];
57	}
58	
59	export function MapPanel({ vehicles, thermals, center = DEFAULT_CENTER }: MapPanelProps) {
60	  const containerRef = useRef<HTMLDivElement>(null);
61	  const mapRef = useRef<L.Map | null>(null);
62	  const ringLayersRef = useRef<L.Circle[]>([]);
63	  const pinLayersRef = useRef<L.Marker[]>([]);
64	  const [selectedStation, setSelectedStation] = useState<Station | null>(null);
65	  const [mapReady, setMapReady] = useState(false);
66	
67	  // Lazy-load Leaflet (it accesses window at import time)
68	  useEffect(() => {
69	    if (typeof window === "undefined" || mapRef.current) return;
70	
71	    let cancelled = false;
72	
73	    import("leaflet").then((L) => {
74	      if (cancelled || mapRef.current) return;
75	
76	      fixLeafletIcons(L);
77	
78	      const container = containerRef.current;
79	      if (!container) return;
80	
81	      const map = L.map(container, {
82	        center,
83	        zoom: 8,
84	        zoomControl: true,
85	      });
86	
87	      L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
88	        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',
89	        maxZoom: 18,
90	      }).addTo(map);
91	
92	      mapRef.current = map;
93	      setMapReady(true);
94	    });
95	
96	    return () => {
97	      cancelled = true;
98	      if (mapRef.current) {
99	        mapRef.current.remove();
100	        mapRef.current = null;
101	      }
102	    };
103	    // eslint-disable-next-line react-hooks/exhaustive-deps
104	  }, []);
105	
106	  // Update range rings whenever vehicles or thermals change
107	  useEffect(() => {
108	    if (!mapReady || !mapRef.current) return;
109	
110	    import("leaflet").then((L) => {
111	      const map = mapRef.current;
112	      if (!map) return;
113	
114	      // Remove old rings
115	      ringLayersRef.current.forEach((c) => c.remove());
116	      ringLayersRef.current = [];
117	
118	      vehicles.forEach((v, idx) => {
119	        const thermal = thermals[v.id];
120	        if (!thermal) return;
121	        const color = VEHICLE_COLORS[idx % VEHICLE_COLORS.length];
122	        const rangeKm = thermal.range_km;
123	
124	        // 100% range ring
125	        const ring100 = L.circle(center, {
126	          radius: rangeKm * 1000,
127	          color,
128	          weight: 2,
129	          fillOpacity: 0.04,
130	          fillColor: color,
131	        }).addTo(map);
132	        ring100.bindTooltip(`${v.model} ${v.trim_label} — ${Math.round(rangeKm)} km`);
133	
134	        // 50% range ring
135	        const ring50 = L.circle(center, {
136	          radius: (rangeKm * 0.5) * 1000,
137	          color,
138	          weight: 1,
139	          dashArray: "4 4",
140	          fillOpacity: 0.02,
141	          fillColor: color,
142	        }).addTo(map);
143	        ring50.bindTooltip(`${v.model} ${v.trim_label} — 50% (${Math.round(rangeKm * 0.5)} km)`);
144	
145	        ringLayersRef.current.push(ring100, ring50);
146	      });
147	    });
148	  }, [mapReady, vehicles, thermals, center]);
149	
150	  // Place charger pins (hardcoded fallback; OCM live data in a future pass)
151	  const loadPins = useCallback(
152	    (L: typeof import("leaflet"), stations: Station[]) => {
153	      const map = mapRef.current;
154	      if (!map) return;
155	
156	      pinLayersRef.current.forEach((m) => m.remove());
157	      pinLayersRef.current = [];
158	
159	      stations.forEach((station) => {
160	        const marker = L.marker([station.lat, station.lng]).addTo(map);
161	        marker.on("click", () => setSelectedStation(station));
162	        marker.bindTooltip(`${station.network} — ${station.kw} kW`);
163	        pinLayersRef.current.push(marker);
164	      });
165	    },
166	    [],
167	  );
168	
169	  useEffect(() => {
170	    if (!mapReady) return;
171	    import("leaflet").then((L) => loadPins(L, ONTARIO_DCFC_FALLBACK));
172	  }, [mapReady, loadPins]);
173	
174	  return (
175	    <div className="relative">
176	      {/* Map container */}
177	      <div
178	        ref={containerRef}
179	        className="w-full rounded-lg overflow-hidden border border-ink-700"
180	        style={{ height: "420px" }}
181	      />
182	
183	      {/* Legend */}
184	      <div className="mt-3 flex flex-wrap gap-4">
185	        {vehicles.map((v, idx) => {
186	          const color = VEHICLE_COLORS[idx % VEHICLE_COLORS.length];
187	          const thermal = thermals[v.id];
188	          return (
189	            <div key={v.id} className="flex items-center gap-2 text-xs text-ink-300">
190	              <span
191	                className="inline-block w-3 h-3 rounded-full flex-shrink-0"
192	                style={{ backgroundColor: color }}
193	              />
194	              <span>
195	                {v.model} {v.trim_label}
196	                {thermal && (
197	                  <span className="text-ink-500 ml-1">
198	                    {Math.round(thermal.range_km)} km
199	                  </span>
200	                )}
201	              </span>
202	            </div>
203	          );
204	        })}
205	        <div className="flex items-center gap-2 text-xs text-ink-500">
206	          <span className="text-base">⚡</span>
207	          DCFC stations (15 Ontario fallback)
208	        </div>
209	      </div>
210	
211	      {/* Station sidecar */}
212	      {selectedStation && (
213	        <div className="mt-3 bg-ink-800 border border-ink-700 rounded-lg p-4 text-sm">
214	          <div className="flex justify-between items-start">
215	            <div>
216	              <div className="font-medium text-ink-100">{selectedStation.name}</div>
217	              <div className="text-ink-400 mt-1">
218	                {selectedStation.network} · {selectedStation.kw} kW
219	              </div>
220	            </div>
221	            <button
222	              onClick={() => setSelectedStation(null)}
223	              className="text-ink-500 hover:text-ink-300 text-lg leading-none ml-4"
224	            >
225	              ×
226	            </button>
227	          </div>
228	        </div>
229	      )}
230	    </div>
231	  );
232	}
