1	import { useState } from "react";
2	import { FilterBar } from "./components/FilterBar";
3	import { BrandList } from "./components/BrandList";
4	import { CompareTray } from "./components/CompareTray";
5	import { CompareView } from "./components/CompareView";
6	import { useAppStore } from "./store/useAppStore";
7	
8	function App() {
9	  const [compareOpen, setCompareOpen] = useState(false);
10	  const { plainMode, setPlainMode } = useAppStore();
11	
12	  return (
13	    <div className="min-h-screen flex flex-col bg-ink-900 text-ink-100 font-body">
14	      <header className="px-6 py-4 border-b border-ink-700 bg-ink-800/40 flex items-center gap-4 flex-wrap">
15	        <h1 className="font-display text-xl tracking-tight">EV Dashboard</h1>
16	        <span className="text-xs text-ink-400">
17	          Canadian EV / PHEV / EREV comparison
18	        </span>
19	        <span className="ml-auto flex items-center gap-3">
20	          {/* Plain / Geek toggle */}
21	          <button
22	            onClick={() => setPlainMode(!plainMode)}
23	            aria-pressed={plainMode}
24	            aria-label={plainMode ? "Switch to technical labels" : "Switch to plain language"}
25	            className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium border transition-colors ${
26	              plainMode
27	                ? "bg-accent-blue/20 border-accent-blue text-accent-blue"
28	                : "bg-ink-700 border-ink-600 text-ink-400 hover:border-ink-500 hover:text-ink-300"
29	            }`}
30	          >
31	            <span className="text-[10px]">{plainMode ? "Plain" : "Geek"}</span>
32	            <span className="opacity-60">·</span>
33	            <span className="text-[10px] opacity-60">{plainMode ? "Geek" : "Plain"}</span>
34	          </button>
35	          <span className="text-xs text-ink-500 hidden sm:inline">
36	            Long-range trims only · All numbers cited
37	          </span>
38	        </span>
39	      </header>
40	
41	      <FilterBar />
42	
43	      <main className="flex-1">
44	        <BrandList />
45	      </main>
46	
47	      <footer className="px-6 py-3 border-t border-ink-700 bg-ink-800/40 text-xs text-ink-500 flex items-center gap-4">
48	        <span>Schema v0.1 · Seed data · Verify all numbers before purchase decisions.</span>
49	        <span className="ml-auto">
50	          Federal iZEV: paused/uncertain 2026 · Ontario provincial rebate: none
51	        </span>
52	      </footer>
53	
54	      <CompareTray onOpen={() => setCompareOpen(true)} />
55	      {compareOpen && <CompareView onClose={() => setCompareOpen(false)} />}
56	    </div>
57	  );
58	}
59	
60	export default App;
